// Liquid glass widget kit — see design.md.
//
// Performance note. `BackdropFilter` forces a saveLayer and re-rasterises
// everything behind it; stacking several drops frames on the mid-range Android
// hardware most of this app's users carry. So only [GlassSurface] with
// `live: true` actually blurs, and no screen should mount more than
// [FvGlass.blurBudget] of those. Cards and rows use the tinted-fill path, which
// costs nothing and is visually near-identical at card scale.
import 'dart:ui' show ImageFilter;

import 'package:family_veda/theme/app_theme.dart';
import 'package:flutter/material.dart';

/// The ambient colour field that glass surfaces blur.
///
/// Without something behind it, a blur has nothing to do and every glass
/// surface degrades to a flat translucent box.
class AmbientBackground extends StatelessWidget {
  const AmbientBackground({super.key, required this.child});

  final Widget child;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final ground = isDark ? AppColors.backgroundDark : AppColors.background;
    final opacity = isDark ? 0.42 : 0.34;

    return DecoratedBox(
      decoration: BoxDecoration(color: ground),
      child: Stack(
        children: [
          Positioned.fill(
            child: IgnorePointer(
              child: CustomPaint(
                painter: _MeshPainter(opacity: opacity),
              ),
            ),
          ),
          child,
        ],
      ),
    );
  }
}

class _MeshPainter extends CustomPainter {
  const _MeshPainter({required this.opacity});

  final double opacity;

  @override
  void paint(Canvas canvas, Size size) {
    void orb(Color color, Offset centre, double radius) {
      final paint = Paint()
        ..shader = RadialGradient(
          colors: [color.withValues(alpha: opacity), color.withValues(alpha: 0)],
        ).createShader(Rect.fromCircle(center: centre, radius: radius));
      canvas.drawCircle(centre, radius, paint);
    }

    orb(AppColors.orbA, Offset(size.width * 0.08, size.height * 0.06), size.width * 0.72);
    orb(AppColors.orbB, Offset(size.width * 0.98, size.height * 0.30), size.width * 0.80);
    orb(AppColors.orbC, Offset(size.width * 0.40, size.height * 1.02), size.width * 0.74);
  }

  @override
  bool shouldRepaint(_MeshPainter oldDelegate) => oldDelegate.opacity != opacity;
}

/// The glass primitive.
///
/// Set [live] only for surfaces that genuinely float above scrolling content —
/// app bars, tab bars, sheets. Everything else should leave it false.
class GlassSurface extends StatelessWidget {
  const GlassSurface({
    super.key,
    required this.child,
    this.live = false,
    this.blur = FvGlass.blurRegular,
    this.borderRadius = const BorderRadius.all(Radius.circular(20)),
    this.padding = EdgeInsets.zero,
    this.shadow = true,
  });

  final Widget child;
  final bool live;
  final double blur;
  final BorderRadius borderRadius;
  final EdgeInsetsGeometry padding;
  final bool shadow;

  @override
  Widget build(BuildContext context) {
    final g = context.glass;

    final surface = DecoratedBox(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [g.fillHigh, g.fillLow],
        ),
        border: Border.all(color: g.edge),
        borderRadius: borderRadius,
        boxShadow: shadow
            ? [
                BoxShadow(
                  color: g.cast,
                  blurRadius: 30,
                  offset: const Offset(0, 14),
                  spreadRadius: -10,
                ),
              ]
            : null,
      ),
      child: Padding(padding: padding, child: child),
    );

    if (!live) return surface;

    return ClipRRect(
      borderRadius: borderRadius,
      child: BackdropFilter(
        filter: ImageFilter.blur(sigmaX: blur, sigmaY: blur),
        child: surface,
      ),
    );
  }
}

/// A tappable glass card. Non-live by design — a list of these would blow the
/// blur budget instantly.
class GlassCard extends StatelessWidget {
  const GlassCard({
    super.key,
    required this.child,
    this.onTap,
    this.padding = const EdgeInsets.all(16),
  });

  final Widget child;
  final VoidCallback? onTap;
  final EdgeInsetsGeometry padding;

  @override
  Widget build(BuildContext context) {
    const radius = BorderRadius.all(Radius.circular(20));
    return GlassSurface(
      borderRadius: radius,
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: onTap,
          borderRadius: radius,
          child: Padding(padding: padding, child: child),
        ),
      ),
    );
  }
}

/// Opaque surface for content that must never blend into its background.
///
/// Clinical Rules 1 and 2: unapproved AI output is always [FvGlass.agent]
/// violet and always opaque. Rule 10: the emergency screen is solid.
class SolidSurface extends StatelessWidget {
  const SolidSurface({
    super.key,
    required this.child,
    required this.color,
    this.padding = const EdgeInsets.all(16),
  });

  const SolidSurface.agent({super.key, required this.child, this.padding = const EdgeInsets.all(16)})
      : color = null;

  final Widget child;
  final Color? color;
  final EdgeInsetsGeometry padding;

  @override
  Widget build(BuildContext context) {
    final fill = color ?? context.glass.agent;
    return DecoratedBox(
      decoration: BoxDecoration(
        color: fill,
        borderRadius: const BorderRadius.all(Radius.circular(20)),
        boxShadow: [
          BoxShadow(
            color: fill.withValues(alpha: 0.34),
            blurRadius: 28,
            offset: const Offset(0, 12),
            spreadRadius: -10,
          ),
        ],
      ),
      child: Padding(padding: padding, child: child),
    );
  }
}

/// Floating glass app bar. Counts against the blur budget.
class GlassAppBar extends StatelessWidget implements PreferredSizeWidget {
  const GlassAppBar({
    super.key,
    required this.title,
    this.actions,
    this.leading,
  });

  final Widget title;
  final List<Widget>? actions;
  final Widget? leading;

  @override
  Size get preferredSize => const Size.fromHeight(kToolbarHeight);

  @override
  Widget build(BuildContext context) {
    return ClipRect(
      child: BackdropFilter(
        filter: ImageFilter.blur(
          sigmaX: FvGlass.blurThick,
          sigmaY: FvGlass.blurThick,
        ),
        child: DecoratedBox(
          decoration: BoxDecoration(
            color: context.glass.fillLow,
            border: Border(bottom: BorderSide(color: context.glass.edgeDim)),
          ),
          child: AppBar(
            title: title,
            actions: actions,
            leading: leading,
            backgroundColor: Colors.transparent,
            elevation: 0,
          ),
        ),
      ),
    );
  }
}

/// Status pill. Colour is never the only signal — every pill carries a label
/// and a leading shape marker.
class GlassPill extends StatelessWidget {
  const GlassPill({super.key, required this.label, required this.color});

  final String label;
  final Color color;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.fromLTRB(8, 4, 11, 4),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.16),
        borderRadius: const BorderRadius.all(Radius.circular(999)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Container(
            width: 6,
            height: 6,
            decoration: BoxDecoration(
              color: color,
              borderRadius: const BorderRadius.all(Radius.circular(2)),
            ),
          ),
          const SizedBox(width: 7),
          Text(
            label,
            style: TextStyle(
              color: color,
              fontSize: 12,
              fontWeight: FontWeight.w700,
              letterSpacing: 0.02,
            ),
          ),
        ],
      ),
    );
  }
}
